// Turn the JSONL test file into one item per labelled message.
const settings = $('Eval settings').first().json;
const lines = String($json.data ?? '').split('\n').map((l) => l.trim()).filter(Boolean);
const group = { en: 'english', am: 'amharic', lt: 'amharic_latin' };
return lines.map((line) => {
  const row = JSON.parse(line);
  return {
    json: {
      id: row.id,
      text: row.text,
      expected_category: row.category,
      expected_urgency: row.urgency,
      lang_group: group[row.id.slice(0, 2)] ?? 'other',
      channel: 'eval',
      model: settings.model || undefined,
      ollama_url: settings.ollama_url || undefined,
    },
  };
});

// Score the model: accuracy, per-category precision/recall, confusion matrix,
// accuracy per language, and how often each guardrail fired.
const rows = $input.all().map((i) => i.json);
const CATS = ['order_status', 'payment', 'product_question', 'complaint', 'spam', 'other', 'needs_human'];
const pct = (a, b) => (b ? Math.round((1000 * a) / b) / 10 : 0);

const n = rows.length;
const correct = rows.filter((r) => r.category === r.expected_category).length;
const urgencyCorrect = rows.filter((r) => r.urgency === r.expected_urgency).length;

const confusion = {};                                   // confusion[expected][predicted]
for (const r of rows) {
  confusion[r.expected_category] ??= {};
  confusion[r.expected_category][r.category] = (confusion[r.expected_category][r.category] ?? 0) + 1;
}
const perCategory = {};
for (const c of CATS.slice(0, 6)) {
  const tp = rows.filter((r) => r.expected_category === c && r.category === c).length;
  const predicted = rows.filter((r) => r.category === c).length;
  const actual = rows.filter((r) => r.expected_category === c).length;
  perCategory[c] = { precision: pct(tp, predicted), recall: pct(tp, actual), support: actual };
}
const byLanguage = {};
for (const g of [...new Set(rows.map((r) => r.lang_group))]) {
  const sub = rows.filter((r) => r.lang_group === g);
  byLanguage[g] = { n: sub.length, accuracy: pct(sub.filter((r) => r.category === r.expected_category).length, sub.length) };
}
const guardrails = {};
for (const r of rows) if (r.problem) guardrails[r.problem] = (guardrails[r.problem] ?? 0) + 1;
// Dangerous miss: an urgent message the bot would NOT escalate to the owner.
const missedUrgent = rows.filter((r) => r.expected_urgency === 'high' && !['urgent', 'needs_human'].includes(r.route));

const misses = rows
  .filter((r) => r.category !== r.expected_category)
  .map((r) => ({ id: r.id, expected: r.expected_category, got: r.category, problem: r.problem, llm_error: r.llm_error, text: r.text }));

const report = {
  model: rows[0]?.model,
  n,
  accuracy: pct(correct, n),
  urgency_accuracy: pct(urgencyCorrect, n),
  missed_urgent: missedUrgent.map((r) => r.id),
  by_language: byLanguage,
  per_category: perCategory,
  guardrails,
  confusion,
  misses,
};
const md = [
  '| model | n | category acc | urgency acc | urgent missed | ' + Object.keys(byLanguage).join(' | ') + ' |',
  '|' + ' --- |'.repeat(5 + Object.keys(byLanguage).length),
  '| ' + [report.model, n, report.accuracy + '%', report.urgency_accuracy + '%', missedUrgent.length,
    ...Object.values(byLanguage).map((v) => v.accuracy + '%')].join(' | ') + ' |',
].join('\n');
return [{ json: { ...report, markdown_row: md } }];
